inline.scriptContent:
$ErrorActionPreference = 'Stop'
$preview = '{{CleanupPreview}}' -eq 'true'
$connect = '{{ConnExBaseUrl}}'.TrimEnd('/') + '/'
$connectHeaders = @{ 'x-api-key' = '{{ConnExApiKey}}'; accept = 'application/json' }
function Split-List([string]$Text) { @($Text -split '\|' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
$keepStrategies = Split-List '{{KeepStrategies}}'
$keepConfigurations = Split-List '{{KeepServiceConfigurations}}'
function Get-Rows($Response) {
    if ($null -eq $Response) { return @() }
    if ($Response -is [array]) { return $Response }
    if ($Response.PSObject.Properties.Name -contains 'data') { return @($Response.data) }
    @($Response)
}
function Get-Field($Row, [string[]]$Names) { foreach ($n in $Names) { $v = $Row.$n; if ($v) { return [string]$v } }; $null }
# Returns the status code plus a short reason. A 401 body echoes the API key, so for 401 only the code is kept;
# any other failure body is reduced to its error text, with the API key masked in case the service echoes it.
$secretValues = @('{{ConnExApiKey}}') | Where-Object { $_ }
function Get-Reason([string]$Body) {
    if (-not $Body) { return '' }
    $text = $Body
    try {
        $json = $Body | ConvertFrom-Json -ErrorAction Stop
        $parts = @(foreach ($n in 'message', 'Message', 'title', 'detail', 'errors', 'Errors') {
            $v = $json.$n; if ($v) { if ($v -is [string]) { $v } else { ConvertTo-Json -Compress -Depth 5 -InputObject $v } } })
        if ($parts.Count) { $text = $parts -join ' | ' }
    } catch { }
    foreach ($s in $secretValues) { $text = $text.Replace($s, '***') }
    $text = ($text -replace '\s+', ' ').Trim()
    if ($text.Length -gt 400) { $text = $text.Substring(0, 400) + '...' }
    $text
}
function Invoke-Delete([string]$Uri, [hashtable]$Headers) {
    try {
        $r = Invoke-WebRequest -Method Delete -Uri $Uri -Headers $Headers -SkipHttpErrorCheck -TimeoutSec 300
        $code = [int]$r.StatusCode
        $reason = if ($code -in 200, 204, 404, 401) { '' } else { Get-Reason ([string]$r.Content) }
        [pscustomobject]@{ Code = $code; Reason = $reason }
    } catch { [pscustomobject]@{ Code = -1; Reason = (Get-Reason $_.Exception.Message) } }
}
function Format-Failure([string]$What, $Result) { if ($Result.Reason) { "$What -> $($Result.Code): $($Result.Reason)" } else { "$What -> $($Result.Code)" } }

$strategies = @(Get-Rows (Invoke-RestMethod -Uri "${connect}v1/Connect/Strategies" -Headers $connectHeaders -TimeoutSec 120) |
    ForEach-Object { [pscustomobject]@{ Id = (Get-Field $_ 'id', 'Id', 'uid', 'Uid'); Name = (Get-Field $_ 'name', 'Name') } })
$configurations = @(Get-Rows (Invoke-RestMethod -Uri "${connect}v1/Connect/Configurations" -Headers $connectHeaders -TimeoutSec 120) |
    ForEach-Object { [pscustomobject]@{ Id = (Get-Field $_ 'id', 'Id', 'uid', 'Uid'); Name = (Get-Field $_ 'name', 'Name') } })
if (@($strategies | Where-Object { -not $_.Id }).Count -or @($configurations | Where-Object { -not $_.Id }).Count) { throw 'A Connect strategy or service configuration came back without an id; the response shape changed.' }

$deleteStrategies = @($strategies | Where-Object { $_.Name -notin $keepStrategies })
$deleteConfigurations = @($configurations | Where-Object { $_.Name -notin $keepConfigurations })
"Strategies: $($strategies.Count) found, $($deleteStrategies.Count) to delete: $(($deleteStrategies.Name | Sort-Object) -join '; ')"
"Service configurations: $($configurations.Count) found, $($deleteConfigurations.Count) to delete: $(($deleteConfigurations.Name | Sort-Object) -join '; ')"
'Entities: none are deleted by this cleanup.'
if ($preview) { 'PREVIEW ONLY: nothing was deleted.'; return }

$failures = [System.Collections.Generic.List[string]]::new()
foreach ($s in $deleteStrategies) {
    $r = Invoke-Delete "${connect}v1/Connect/Strategies?IntegrationStrategyUids=$($s.Id)" $connectHeaders
    if ($r.Code -notin 200, 204, 404) { $failures.Add((Format-Failure "strategy '$($s.Name)'" $r)) }
}
foreach ($c in $deleteConfigurations) {
    $r = Invoke-Delete "${connect}v1/Connect/Configurations?ConfigurationUids=$($c.Id)" $connectHeaders
    if ($r.Code -notin 200, 204, 404) { $failures.Add((Format-Failure "service configuration '$($c.Name)'" $r)) }
}
"Deleted $($deleteStrategies.Count) strategies and $($deleteConfigurations.Count) service configurations ($($failures.Count) failed)."
if ($failures.Count) { throw "Cleanup left $($failures.Count) item(s): $($failures -join '; ')" }
'Cleanup complete.'
